INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '三集合非标准型', 'kp-xingce-quantity-math-operation-inclusion-exclusion-three-non-std', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "三集合非标准型"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心公式：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "总数 = A+B+C - 满足两项的人 - 2 × ABC + 都不满足。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "极高频考点！题目不给你具体的“满足A和B”、“满足A和C”的人数，而是给了一个打包的总数：“满足两项的有 x 人”。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心破题"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "当题目说“满足两项的有 x 人”时，这 x 个人在 A+B+C 中被加了 2 次，多加了 1 次，所以减去这 x 个人即可。"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "而核心的 ABC 在 A+B+C 中被加了 3 次，多加了 2 次。所以在减的时候，必须减去 2 × ABC！这就是它和标准型公式最大的区别！"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[看到题目给了打包的'满足两项的人数'] --> B[抛弃标准型公式, 启用非标准型]\nB --> C[总数 = A + B + C - (只满足两项的总和) - 2 * (三项都满足) + 都不满足]\nC --> D[代入数值, 求解未知数]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 100人。A(50)，B(40)，C(30)。满足两项的共 20 人。三项都不满足的 5 人。求三项都满足几人？"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "识别：非标准型公式。因为出现了“满足两项的共 20 人”。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "列式：100 = 50 + 40 + 30 - 20 - 2 × ABC + 5。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "求解：100 = 105 - 2 × ABC。2 × ABC = 5。ABC = 2.5。（假设数据，领会精神）。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "生搬硬套死公式：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "遇到非标准型，千万别去设 AB=x, AC=y, BC=z，然后列方程 x+y+z=20，再代入标准型公式！那样做你的 ABC 扣减次数必定搞错。记住，出现“满足两项”，直接套“减2倍ABC”公式。"}]}]}]}$$ AS jsonb), NULL, '三集合非标准型的核心考点与实战推导。', category_node.id, CAST('["数量关系", "容斥问题", "三集合非标准型"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_quantity_math_operation_inclusion_exclusion_three_non_std", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
